"use client";

import "./fieldset.css";

import type React from "react";

import { Fieldset as BaseFieldset } from "@base-ui/react/fieldset";
import { cn } from "tailwind-variants";

import { FieldsetContext, useFieldsetContext } from "./fieldset.context";
import { fieldsetVariants, type FieldsetVariants } from "./fieldset.variants";

export type FieldsetProps = FieldsetVariants & React.ComponentProps<typeof BaseFieldset.Root>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/fieldset/content.md
 */
export const FieldsetRoot = ({ children, className, variant, ...props }: FieldsetProps) => {
  const slots = fieldsetVariants({ variant });

  return (
    <FieldsetContext.Provider value={{ slots }}>
      <BaseFieldset.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseFieldset.Root>
    </FieldsetContext.Provider>
  );
};

export type FieldsetLegendProps = React.ComponentProps<typeof BaseFieldset.Legend>;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/fieldset/content.md
 */
export const FieldsetLegend = ({ className, ...props }: FieldsetLegendProps) => {
  const { slots } = useFieldsetContext();
  return <BaseFieldset.Legend className={cn(slots.legend(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const fieldsetVariants = tv({
  slots: {
    root: "fieldset",
    legend: "fieldset__legend",
  },
  variants: {
    variant: {
      default: {
        root: "fieldset--default",
      },
      bordered: {
        root: "fieldset--bordered",
      },
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

export type FieldsetVariants = VariantProps<typeof fieldsetVariants>;

"use client";

import { createContext, useContext } from "react";

import { fieldsetVariants } from "./fieldset.variants";

export type FieldsetContext = {
  slots: ReturnType<typeof fieldsetVariants>;
};

export const FieldsetContext = createContext<FieldsetContext | null>(null);

export const useFieldsetContext = () => {
  const context = useContext(FieldsetContext);
  return context ?? { slots: fieldsetVariants() };
};

.fieldset {
  @apply flex w-full flex-col gap-4 border-0 p-0 m-0 text-foreground;
}

.fieldset--bordered {
  @apply rounded-lg border border-border p-4;
}

.fieldset__legend {
  @apply border-b border-border text-base font-semibold text-foreground pb-1 mb-1;
}

import { FieldsetLegend, FieldsetRoot } from "./fieldset";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/fieldset/content.md
 */
export const Fieldset = {
  Legend: FieldsetLegend,
  Root: FieldsetRoot,
};

export { FieldsetLegend, FieldsetRoot };

export type { FieldsetLegendProps, FieldsetProps } from "./fieldset";
export { FieldsetContext, useFieldsetContext } from "./fieldset.context";
export { type FieldsetVariants, fieldsetVariants } from "./fieldset.variants";
